static boolean hasDuplicate(int[] values) {
    java.util.Set<Integer> seen = new java.util.HashSet<>();
    for (int value : values) {
        if (!seen.add(value)) return true;
    }
    return false;
}

static boolean pairExists(int[] a, long target) {
    int left = 0, right = a.length - 1;
    while (left < right) {
        long sum = (long) a[left] + a[right];
        if (sum == target) return true;
        if (sum < target) left++; else right--;
    }
    return false;
}

static int longestDistinct(int[] a) {
    java.util.Map<Integer,Integer> counts = new java.util.HashMap<>();
    int left = 0, best = 0;
    for (int right = 0; right < a.length; right++) {
        counts.merge(a[right], 1, Integer::sum);
        while (counts.get(a[right]) > 1) {
            counts.put(a[left], counts.get(a[left]) - 1);
            left++;
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

static int lowerBound(int[] a, int target) {
    int left = 0, right = a.length;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (a[mid] < target) left = mid + 1;
        else right = mid;
    }
    return left;
}

static int[] nextLarger(int[] a) {
    int[] answer = new int[a.length];
    java.util.Arrays.fill(answer, -1);
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i < a.length; i++) {
        while (!stack.isEmpty() && a[stack.peek()] < a[i]) {
            answer[stack.pop()] = a[i];
        }
        stack.push(i);
    }
    return answer;
}

static final class Node {
    final int value; Node next;
    Node(int value) { this.value = value; }
}
static Node reverse(Node head) {
    Node previous = null, current = head;
    while (current != null) {
        Node next = current.next;
        current.next = previous;
        previous = current;
        current = next;
    }
    return previous;
}

static final class TreeNode {
    int value; TreeNode left, right;
    TreeNode(int value) { this.value = value; }
}
static int height(TreeNode root) {
    if (root == null) return 0;
    return 1 + Math.max(height(root.left), height(root.right));
}

static int[] distances(java.util.List<java.util.List<Integer>> graph, int source) {
    int[] distance = new int[graph.size()];
    java.util.Arrays.fill(distance, -1);
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    distance[source] = 0; queue.add(source);
    while (!queue.isEmpty()) {
        int node = queue.remove();
        for (int next : graph.get(node)) {
            if (distance[next] != -1) continue;
            distance[next] = distance[node] + 1;
            queue.add(next);
        }
    }
    return distance;
}

static java.util.List<java.util.List<Integer>> subsets(int[] a) {
    var result = new java.util.ArrayList<java.util.List<Integer>>();
    collect(a, 0, new java.util.ArrayList<>(), result);
    return result;
}
static void collect(int[] a, int i, java.util.List<Integer> path,
                    java.util.List<java.util.List<Integer>> result) {
    if (i == a.length) { result.add(new java.util.ArrayList<>(path)); return; }
    collect(a, i + 1, path, result);
    path.add(a[i]);
    collect(a, i + 1, path, result);
    path.remove(path.size() - 1);
}

static long bestNonAdjacent(int[] values) {
    long skip = 0, take = Long.MIN_VALUE;
    for (int value : values) {
        long nextTake = skip + value;
        long nextSkip = Math.max(skip, take);
        take = nextTake; skip = nextSkip;
    }
    return Math.max(skip, take);
}
